INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('DaVinci Resolve Official Editing & Color Grading Beginner''s Guide (Full Manual)', '[Tác giả: Blackmagic Design Official Education Division] - Sách hướng dẫn chính thức từ nhà sản xuất Blackmagic Design: quy trình dựng phim chuyên nghiệp trên Cut Page và Edit Page, làm chủ timeline và phím tắt dựng.', 'http://localhost:5000/uploads/materials/davinci-resolve-official-editing-color-grading-beg-1789396726951.pdf', 'PDF', 1104836, 458, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Grammar of the Film Language: Cinematic Framing, Cutting, and Continuity', '[Tác giả: Daniel Arijon (Celebrated Film Director & Cinematographer)] - Bách khoa toàn thư về ngôn ngữ hình ảnh điện ảnh: góc quay, trục 180 độ (180-Degree Rule), kỹ thuật dựng nối hình (Match Cut, Jump Cut) và chuyển cảnh nhịp nhàng.', 'http://localhost:5000/uploads/materials/grammar-of-the-film-language-cinematic-framing-cut-1789396729554.pdf', 'PDF', 107346, 171, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('In the Blink of an Eye: A Perspective on Film Editing and the Rule of Six', '[Tác giả: Walter Murch (Hollywood Legendary Editor - 3 Academy Awards)] - Triết lý dựng phim kinh điển thế giới: Quy tắc 6 tiêu chí cắt cảnh (Cảm xúc chiếm 51%, Cốt truyện 23%, Nhịp điệu 10%, Điểm nhìn 7%, Màn ảnh 2D 5%, Không gian 3D 4%).', 'http://localhost:5000/uploads/materials/in-the-blink-of-an-eye-a-perspective-on-film-editi-1789396730998.pdf', 'PDF', 317417, 111, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Color Correction and Color Grading Science: Log Profiles, LUTs, and Rec.709 Standards', '[Tác giả: Society of Motion Picture and Television Engineers (SMPTE)] - Khoa học hiệu chỉnh màu sắc phim ảnh: đọc biểu đồ Waveform, Vectorscope, Parade, xử lý dải động rộng (Dynamic Range), Log to Rec.709 và tạo Color Look (Teal & Orange).', 'http://localhost:5000/uploads/materials/color-correction-and-color-grading-science-log-pro-1789396732720.pdf', 'PDF', 120645, 161, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Video Post-Production Workflow: Codecs, Bitrates, and Apple ProRes / H.265 Standards', '[Tác giả: Apple Pro Video Applications & Adobe Video Engineering] - Cẩm nang kỹ thuật về chuẩn nén video: sự khác biệt giữa Intra-frame (ProRes, DNxHR) và Inter-frame (H.264, HEVC), tốc độ khung hình (24/30/60 FPS) và tối ưu hóa Render.', 'http://localhost:5000/uploads/materials/video-post-production-workflow-codecs-bitrates-and-1789396734065.pdf', 'PDF', 323091, 132, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Audio Post-Production for Video: Dialogue Cleanup, Foley, EQ, and -14 LUFS Standards', '[Tác giả: Audio Engineering Society (AES) & Fairlight Audio] - Kỹ nghệ xử lý âm thanh hậu kỳ phim: lọc tạp âm (Noise Reduction), cân bằng âm sắc EQ, nén Compressor, thiết kế tiếng động Foley và tiêu chuẩn âm lượng -14 LUFS cho Web/YouTube.', 'http://localhost:5000/uploads/materials/audio-post-production-for-video-dialogue-cleanup-f-1789396735826.pdf', 'PDF', 3433632, 334, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Visual Effects (VFX) Compositing: Chroma Keying, Tracking, and Roto Workflows', '[Tác giả: ACM SIGGRAPH & The Foundry Research Group] - Kỹ thuật kỹ xảo điện ảnh: tách phông xanh (Green Screen Keying), theo dõi chuyển động (Planar/Camera Tracking), kỹ thuật Rotoscoping và hòa trộn ánh sáng đa lớp.', 'http://localhost:5000/uploads/materials/visual-effects-vfx-compositing-chroma-keying-track-1789396738804.pdf', 'PDF', 1172762, 302, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('The 12 Principles of Animation Applied to Motion Graphics and Title Sequences', '[Tác giả: Disney Animation Archives & Adobe After Effects Guild] - Ứng dụng 12 nguyên lý hoạt hình (Squash & Stretch, Anticipation, Slow In & Out, Follow Through) vào đồ họa chuyển động, thiết kế intro và typography động.', 'http://localhost:5000/uploads/materials/the-12-principles-of-animation-applied-to-motion-g-1789396741013.pdf', 'PDF', 668251, 166, 22, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('The Official Blender Reference Manual: Modeling, Modifiers, and Node Architectures', '[Tác giả: Blender Foundation (Official Open-Source 3D Creation Suite)] - Tài liệu tham chiếu chính thức toàn diện nhất: cấu trúc Mesh, phím tắt dựng hình, hệ thống Modifier không phá hủy (Non-Destructive) và kiến trúc Geometry Nodes.', 'http://localhost:5000/uploads/materials/the-official-blender-reference-manual-modeling-mod-1789396743104.pdf', 'PDF', 1104836, 69, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Physically Based Rendering (PBR) Texturing and Material Theory (Comprehensive Guide)', '[Tác giả: Allegorithmic / Adobe Substance 3D Research] - Giáo trình vật liệu tả thực PBR: kênh Base Color, Roughness, Metallic, Normal Maps, và mô hình phản xạ quang học Fresnel trong kết xuất 3D.', 'http://localhost:5000/uploads/materials/physically-based-rendering-pbr-texturing-and-mater-1789396745554.pdf', 'PDF', 24854165, 314, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('3D Topology and Subdivision Surface Modeling: Edge Loops, Poles, and Clean Deformation', '[Tác giả: ACM SIGGRAPH Course Notes on Geometric Modeling] - Nguyên lý lưới Topology chuẩn trong diễn họa 3D: kỹ thuật đi đường lưới (Edge Flow), xử lý lưới 4 cạnh (Quads) và triệt tiêu biến dạng khi gắn xương chuyển động.', 'http://localhost:5000/uploads/materials/3d-topology-and-subdivision-surface-modeling-edge-loops-poles-and-1789396751643.pdf', 'PDF', 819383, 54, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Digital Sculpting Anatomy and Organic Modeling Principles in Blender', '[Tác giả: ZBrush & Blender Digital Sculpting Master Group] - Phương pháp điêu khắc số giải phẫu học cơ thể người và sinh vật: sử dụng Dyntopo, Voxel Remesh, các cọ điêu khắc (Clay, Crease, Inflate) và quy trình Retopology.', 'http://localhost:5000/uploads/materials/digital-sculpting-anatomy-and-organic-modeling-pri-1789396753696.pdf', 'PDF', 2215244, 160, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Three-Point Lighting, HDRI Environment Lighting, and Photorealistic Shading', '[Tác giả: Pixar Animation Studios Technical Papers] - Kỹ thuật chiếu sáng điện ảnh trong không gian 3 chiều: đèn chính (Key Light), đèn phụ (Fill Light), đèn ven (Rim Light), môi trường HDRI 32-bit và đổ bóng mềm.', 'http://localhost:5000/uploads/materials/three-point-lighting-hdri-environment-lighting-and-1789396756255.pdf', 'PDF', 120645, 506, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Blender Cycles vs EEVEE: Ray Tracing, Indirect Lighting, and Shader Optimization', '[Tác giả: Blender Foundation Graphics Rendering Team] - Phân tích kiến trúc render: cơ chế dò tia quang học Path Tracing của Cycles so với động cơ thời gian thực Rasterization của EEVEE-Next, tối ưu hóa hạt Noises với OptiX/OpenImageDenoise.', 'http://localhost:5000/uploads/materials/blender-cycles-vs-eevee-ray-tracing-indirect-light-1789396757666.pdf', 'PDF', 631718, 88, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('3D Character Rigging and Skeletal Animation: Forward vs Inverse Kinematics (FK/IK)', '[Tác giả: IEEE Computer Graphics and Applications] - Kỹ thuật gắn xương nhân vật 3D: cấu trúc Armature, bộ điều khiển IK/FK, kỹ thuật bọc da trọng số (Weight Painting) và liên kết Shape Keys biểu cảm khuôn mặt.', 'http://localhost:5000/uploads/materials/3d-character-rigging-and-skeletal-animation-forwar-1789396759613.pdf', 'PDF', 417205, 138, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Hard-Surface Modeling Techniques: Non-Destructive Booleans, Bevels, and Weighted Normals', '[Tác giả: 3D Artist Magazine & ArtStation Learning Series] - Quy trình dựng hình vật thể cơ khí, kiến trúc và xe cộ: làm chủ Boolean Modifiers, Bevel Shader, Weighted Normals và loại bỏ hoàn toàn lỗi vệt đen trên bề mặt cong.', 'http://localhost:5000/uploads/materials/hard-surface-modeling-techniques-non-destructive-b-1789396761464.pdf', 'PDF', 4681034, 46, 23, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Kỹ thuật Đàm phán: Nguyên tắc, Chiến thuật và Xử lý Bế tắc', '[Tác giả: TS. Huỳnh Trường Huy, ThS. Võ Hồng Phượng (Trường Đại học Cần Thơ - CTU)] - Giáo trình chính quy phân tích bản chất, các giai đoạn chuẩn bị, nguyên tắc nhượng bộ, chiến lược đàm phán phân bổ vs hợp tác và nghệ thuật phá vỡ bế tắc.', 'http://localhost:5000/uploads/materials/giao-trinh-ky-thuat-dam-phan-nguyen-tac-chien-thuat-va-xu-ly-be-t-1789397141191.pdf', 'PDF', 1104836, 370, 24, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Kỹ năng Giao tiếp và Đàm phán trong Kinh doanh', '[Tác giả: PGS.TS Dương Thị Liễu, TS. Nguyễn Thị Ngọc Anh (Trường ĐH Kinh tế Quốc dân - NEU)] - Tài liệu đào tạo chuẩn mực về nghi thức giao tiếp thương mại, tâm lý học trong đàm phán, kỹ thuật đặt câu hỏi, lắng nghe tích cực và nghệ thuật thuyết phục đối tác.', 'http://localhost:5000/uploads/materials/giao-trinh-ky-nang-giao-tiep-va-dam-phan-trong-kinh-doanh-1789397143731.pdf', 'PDF', 141971, 193, 24, 2, 'active', NOW(), NOW());
