INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Nghiên cứu Thực nghiệm Kỹ năng Quản lý Thời gian của Sinh viên Đại học', '[Tác giả: Tạp chí Khoa học Giáo dục (ĐHQG TP.HCM & Trường ĐH Sư phạm)] - Công trình nghiên cứu khoa học phân tích nguyên nhân tâm lý dẫn đến thói quen trì hoãn (Procrastination) và các giải pháp hành vi giúp nâng cao tính tự giác kỷ luật.', 'http://localhost:5000/uploads/materials/nghien-cuu-thuc-nghiem-ky-nang-quan-ly-thoi-gian-cua-sinh-vien-da-1789397161439.pdf', 'PDF', 1172762, 501, 25, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Cẩm nang Tối ưu Hiệu suất Làm việc và Làm chủ Thời gian Biểu', '[Tác giả: Trường Đại học Kinh tế Quốc dân (NEU)] - Hệ thống phương pháp lên lịch trình cá nhân khoa học, kỹ thuật phân đoạn thời gian (Time-blocking) và các quy tắc kiểm soát tác nhân gây xao nhãng trong kỷ nguyên số.', 'http://localhost:5000/uploads/materials/cam-nang-toi-uu-hieu-suat-lam-viec-va-lam-chu-thoi-gian-bieu-1789397163740.pdf', 'PDF', 668251, 445, 25, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Getting Things Done (GTD): Nghệ thuật Quản lý Năng suất Không Căng thẳng', '[Tác giả: David Allen Productivity Research Center] - Quy trình 5 bước kinh điển thế giới trong quản trị công việc: Thu thập (Capture), Làm rõ (Clarify), Tổ chức (Organize), Suy ngẫm (Reflect) và Hành động (Engage).', 'http://localhost:5000/uploads/materials/getting-things-done-gtd-nghe-thuat-quan-ly-nang-suat-khong-cang-t-1789397165881.pdf', 'PDF', 819383, 432, 25, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('The 7 Habits of Highly Effective People: Ma trận Thời gian Góc phần tư II', '[Tác giả: Stephen R. Covey Leadership Center] - Triết lý quản trị cuộc đời: tập trung nguồn lực vào Góc phần tư II (Việc quan trọng nhưng không khẩn cấp) để xây dựng tầm nhìn, phòng ngừa rủi ro và phát triển bền vững.', 'http://localhost:5000/uploads/materials/the-7-habits-of-highly-effective-people-ma-tr-n-th-1789397167888.pdf', 'PDF', 2215244, 268, 25, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Deep Work: Quy tắc Tập trung Cao độ trong Một Thế giới Đầy Xao Nhãng', '[Tác giả: GS. Cal Newport (Georgetown University & MIT Press)] - Nền tảng khoa học về trạng thái làm việc sâu (Deep Work), cơ chế phục hồi năng lượng não bộ và phương pháp rèn luyện khả năng tập trung tuyệt đối.', 'http://localhost:5000/uploads/materials/deep-work-quy-tac-tap-trung-cao-do-trong-mot-the-gioi-day-xao-nha-1789397170315.pdf', 'PDF', 631718, 275, 25, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Eat That Frog!: 21 Phương pháp Chấm dứt Trì hoãn và Hoàn thành Công việc', '[Tác giả: Brian Tracy International Institute] - Kỹ thuật tối ưu năng suất nổi tiếng thế giới: phương pháp ABCDE trong xếp thứ tự ưu tiên và nguyên lý giải quyết nhiệm vụ khó khăn nhất vào đầu mỗi ngày làm việc.', 'http://localhost:5000/uploads/materials/eat-that-frog-21-phuong-phap-cham-dut-tri-hoan-va-hoan-thanh-cong-1789397172347.pdf', 'PDF', 417205, 533, 25, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Tư duy Biện luận Ứng dụng: Cấu trúc Lập luận và Phân tích Logic', '[Tác giả: TS. Dương Thị Hoàng Oanh, ThS. Nguyễn Xuân Đạt (NXB Đại học Quốc gia TP.HCM)] - Giáo trình đại học chính thống về nhận diện tiền đề, kết luận, phân tích tính hợp lệ của tam đoạn luận và các kỹ thuật bác bỏ ngụy biện trong nghiên cứu học thuật.', 'http://localhost:5000/uploads/materials/giao-trinh-tu-duy-bien-luan-ung-dung-cau-truc-lap-luan-va-phan-ti-1789397174138.pdf', 'PDF', 1104836, 108, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Cẩm nang Tư duy Phản biện: Khái niệm, Tiêu chuẩn và Bộ Công cụ Phân tích', '[Tác giả: TS. Richard Paul, TS. Linda Elder (Foundation for Critical Thinking & NXB Tổng hợp)] - Tài liệu nền tảng định hình tư duy phản biện hiện đại: 8 yếu tố tư duy (Mục đích, Câu hỏi, Thông tin, Diễn giải...) và 9 tiêu chuẩn trí tuệ phổ quát (Rõ ràng, Chính xác, Sâu sắc...).', 'http://localhost:5000/uploads/materials/cam-nang-tu-duy-phan-bien-khai-niem-tieu-chuan-va-bo-cong-cu-phan-1789397176658.pdf', 'PDF', 4681034, 532, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Phương pháp Sáu Chiếc Mũ Tư duy (Six Thinking Hats) trong Ra Quyết định', '[Tác giả: Viện Sáng tạo Edward de Bono] - Công cụ tư duy đa chiều mang tính cách mạng: tách biệt dữ kiện thực tế (Mũ trắng), trực giác cảm xúc (Mũ đỏ), đánh giá rủi ro (Mũ đen), lợi ích tích cực (Mũ vàng) và ý tưởng đột phá (Mũ xanh lá).', 'http://localhost:5000/uploads/materials/phuong-phap-sau-chiec-mu-tu-duy-six-thinking-hats-trong-ra-quyet--1789397179772.pdf', 'PDF', 24854165, 349, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Phát triển Tư duy Phản biện trong Dạy và Học Bậc Đại học', '[Tác giả: Tạp chí Khoa học Trường Đại học Cần Thơ (CTU)] - Phương pháp sư phạm rèn luyện năng lực hoài nghi tích cực cho sinh viên, kỹ thuật đặt câu hỏi truy vấn bản chất vấn đề và xây dựng lập luận khoa học độc lập.', 'http://localhost:5000/uploads/materials/phat-trien-tu-duy-phan-bien-trong-day-va-hoc-bac-dai-hoc-1789397190974.pdf', 'PDF', 363274, 169, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Asking the Right Questions: A Guide to Critical Thinking (Đặt Câu hỏi Đúng)', '[Tác giả: GS. M. Neil Browne, Stuart M. Keeley (Bowling Green State University)] - Cẩm nang hướng dẫn phương pháp đặt câu hỏi phản biện then chốt: nhận diện giả định ngầm ẩn, phát hiện mâu thuẫn bằng chứng và đánh giá độ tin cậy của số liệu thống kê.', 'http://localhost:5000/uploads/materials/asking-the-right-questions-a-guide-to-critical-thi-1789397193087.pdf', 'PDF', 120645, 47, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Logic Học và Phương pháp Nhận diện Các Lỗi Ngụy biện Thường gặp', '[Tác giả: Khoa Triết học (Trường ĐH Khoa học Xã hội & Nhân văn - ĐHQG Hà Nội)] - Giáo trình hệ thống hóa các bẫy ngụy biện phổ biến: Công kích cá nhân (Ad Hominem), Người rơm (Straw Man), Nhị nguyên giả tạo (False Dilemma) và Dốc trơn trượt (Slippery Slope).', 'http://localhost:5000/uploads/materials/logic-hoc-va-phuong-phap-nhan-dien-cac-loi-nguy-bien-thuong-gap-1789397194458.pdf', 'PDF', 1958911, 284, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('The Demon-Haunted World: Bộ Công cụ Phát hiện Điều Ngụy tạo (Baloney Detection)', '[Tác giả: GS. Carl Sagan (Cornell University) & Ann Druyan] - Phương pháp luận tư duy hoài nghi khoa học của Carl Sagan: 9 quy tắc kiểm chứng bằng chứng và danh sách các lỗi tư duy phi lý trí cần phòng tránh.', 'http://localhost:5000/uploads/materials/the-demon-haunted-world-bo-cong-cu-phat-hien-dieu-nguy-tao-balone-1789397196870.pdf', 'PDF', 939692, 62, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Critical Thinking: Tools for Taking Charge of Your Professional Life', '[Tác giả: Foundation for Critical Thinking Educational Series] - Chiến lược rèn luyện tư duy độc lập và công tâm (Fairminded Thinking), kiểm soát thiên kiến nhận thức chủ quan và nâng cao năng lực ra quyết định chiến lược.', 'http://localhost:5000/uploads/materials/critical-thinking-tools-for-taking-charge-of-your-professional-li-1789397198920.pdf', 'PDF', 558558, 337, 26, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Kỹ năng Lãnh đạo và Quản lý Hiện đại', '[Tác giả: Học viện Quản lý Giáo dục & ĐHQG Hà Nội (VNU)] - Giáo trình tổng quan về khung năng lực lãnh đạo thời đại 4.0: định hình tầm nhìn chiến lược, kỹ năng ủy quyền hiệu quả, quản trị xung đột nội bộ và xây dựng văn hóa tổ chức vững mạnh.', 'http://localhost:5000/uploads/materials/giao-trinh-ky-nang-lanh-dao-va-quan-ly-hien-dai-1789397200986.pdf', 'PDF', 1104836, 453, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Nghệ thuật Lãnh đạo Bản thân và Dẫn dắt Đội ngũ Hiệu suất cao', '[Tác giả: Khoa Quản trị Kinh doanh (Trường Đại học Ngoại thương - FTU)] - Tài liệu đào tạo nguyên tắc lãnh đạo bằng sự gương mẫu (Leading by Example), xây dựng lòng tin, tạo động lực nội tại và nghệ thuật phản hồi mang tính xây dựng.', 'http://localhost:5000/uploads/materials/nghe-thuat-lanh-dao-ban-than-va-dan-dat-doi-ngu-hieu-suat-cao-1789397203581.pdf', 'PDF', 158891, 273, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Kỹ năng Lãnh đạo Tình huống và Tạo Động lực Nhân viên', '[Tác giả: Trường Đại học Kinh tế TP.HCM (UEH)] - Nghiên cứu ứng dụng mô hình lãnh đạo tình huống Hersey-Blanchard: linh hoạt điều chỉnh giữa 4 phong cách Chỉ đạo (Directing), Hướng dẫn (Coaching), Hỗ trợ (Supporting) và Ủy quyền (Delegating).', 'http://localhost:5000/uploads/materials/ky-nang-lanh-dao-tinh-huong-va-tao-dong-luc-nhan-vien-1789397205130.pdf', 'PDF', 141971, 60, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Tâm lý học Quản trị và Văn hóa Lãnh đạo Doanh nghiệp Việt Nam', '[Tác giả: Viện Nghiên cứu Quản lý Kinh tế Trung ương (CIEM)] - Phân tích các đặc thù tâm lý, văn hóa ứng xử của người lao động Việt Nam và các giải pháp lãnh đạo nhân văn, dung hòa lợi ích giữa người lao động và doanh nghiệp.', 'http://localhost:5000/uploads/materials/tam-ly-hoc-quan-tri-va-van-hoa-lanh-dao-doanh-nghiep-viet-nam-1789397206541.pdf', 'PDF', 234449, 490, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('The 21 Irrefutable Laws of Leadership (21 Nguyên tắc Vàng của Lãnh đạo)', '[Tác giả: John C. Maxwell Leadership Foundation] - Bộ nguyên tắc kinh điển định hình năng lực lãnh đạo: Định luật về Chiếc nắp trần (The Law of the Lid), Định luật về Sức ảnh hưởng, Định luật về Kết nối và Trao quyền.', 'http://localhost:5000/uploads/materials/the-21-irrefutable-laws-of-leadership-21-nguyen-tac-vang-cua-lanh-1789397208142.pdf', 'PDF', 868492, 196, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Leaders Eat Last: Tại sao Đội ngũ Gắn kết còn nơi khác thì Tan rã?', '[Tác giả: Simon Sinek Research Institute] - Mô hình ''Vòng tròn An toàn'' (Circle of Safety): cơ chế sinh học của lòng trung thành, trách nhiệm bảo bọc của người đứng đầu và cách tạo dựng môi trường làm việc không sợ hãi.', 'http://localhost:5000/uploads/materials/leaders-eat-last-tai-sao-doi-ngu-gan-ket-con-noi-khac-thi-tan-ra-1789397210311.pdf', 'PDF', 107346, 304, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Harvard Business Review on Leadership (Tuyển tập Nghiên cứu HBR)', '[Tác giả: Harvard Business School Publishing (HBR)] - Tuyển tập các công trình nghiên cứu đột phá về phong cách lãnh đạo chuyển đổi (Transformational Leadership), trí tuệ cảm xúc (EQ) của nhà quản trị và kỹ năng dẫn dắt thay đổi.', 'http://localhost:5000/uploads/materials/harvard-business-review-on-leadership-tuyen-tap-nghien-cuu-hbr-1789397211610.pdf', 'PDF', 317417, 119, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Good to Great: Từ Tốt đến Vĩ đại và Chân dung Nhà Lãnh đạo Cấp độ 5', '[Tác giả: Jim Collins Research Team (Stanford Graduate School of Business)] - Công trình nghiên cứu thực nghiệm 15 năm về các công ty vĩ đại: sự kết hợp nghịch lý giữa lòng khiêm nhường cá nhân và ý chí sắt đá của các nhà lãnh đạo Cấp độ 5.', 'http://localhost:5000/uploads/materials/good-to-great-tu-tot-den-vi-dai-va-chan-dung-nha-lanh-dao-cap-do--1789397213230.pdf', 'PDF', 120645, 500, 27, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Toán học Cao cấp - Tập 1: Đại số và Hình học Giải tích', '[Tác giả: GS.TS Nguyễn Đình Trí (Chủ biên - Trường ĐH Bách Khoa Hà Nội)] - Giáo trình kinh điển về ma trận, định thức, hệ phương trình đại số tuyến tính, cấu trúc không gian vectơ, cơ sở, số chiều và phép biến đổi tuyến tính.', 'http://localhost:5000/uploads/materials/giao-trinh-toan-hoc-cao-cap-tap-1-dai-so-va-hinh-hoc-giai-tich-1789397857860.pdf', 'PDF', 1104836, 291, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Toán học Cao cấp - Tập 2: Giải tích Hàm một biến', '[Tác giả: GS.TS Nguyễn Đình Trí, GS. Tạ Văn Đĩnh (Trường ĐH Bách Khoa Hà Nội)] - Giáo trình chuẩn mực về giới hạn dãy số và hàm số, phép tính vi phân, định lý giá trị trung bình (Rolle, Lagrange, Cauchy), tích phân Riemann và phương trình vi phân cơ bản.', 'http://localhost:5000/uploads/materials/giao-trinh-toan-hoc-cao-cap-tap-2-giai-tich-ham-mot-bien-1789397860503.pdf', 'PDF', 819383, 440, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Giải tích - Tập 3: Hàm nhiều biến và Lý thuyết Chuỗi', '[Tác giả: PGS.TS Đỗ Công Khanh (Chủ biên - Trường ĐH Bách Khoa - ĐHQG TP.HCM)] - Tài liệu chuyên sâu về đạo hàm riêng, cực trị có điều kiện, tích phân kép, tích phân bội ba, tích phân đường, tích phân mặt và lý thuyết chuỗi số / chuỗi Fourier.', 'http://localhost:5000/uploads/materials/giao-trinh-giai-tich-tap-3-ham-nhieu-bien-va-ly-thuyet-chuoi-1789397862857.pdf', 'PDF', 2215244, 426, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Bài tập Toán cao cấp và Tuyển tập Đề thi có Lời giải Chi tiết', '[Tác giả: Khoa Toán - Tin học (Trường Đại học Khoa học Tự nhiên - ĐHQG Hà Nội)] - Hệ thống các dạng bài tập toán cao cấp mẫu, phương pháp giải tối ưu cho bài toán tích phân suy rộng, chuỗi lũy thừa và ứng dụng giải hệ phương trình vi phân.', 'http://localhost:5000/uploads/materials/bai-tap-toan-cao-cap-va-tuyen-tap-de-thi-co-loi-giai-chi-tiet-1789397865657.pdf', 'PDF', 631718, 485, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Calculus: Early Transcendentals (Giáo trình Giải tích Chuẩn Quốc tế)', '[Tác giả: GS. James Stewart (McMaster University & Cengage Learning)] - Bộ giáo trình giải tích hàng đầu thế giới với hệ thống đồ thị hàm số trực quan không gian 3 chiều, các định lý giải tích vi tích phân và bài toán ứng dụng vật lý.', 'http://localhost:5000/uploads/materials/calculus-early-transcendentals-giao-trinh-giai-tich-chuan-quoc-te-1789397867693.pdf', 'PDF', 417205, 239, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Phương trình Vi phân và Ứng dụng trong Mô hình hóa Toán học', '[Tác giả: Viện Toán học (Viện Hàn lâm Khoa học và Công nghệ Việt Nam - VAST)] - Công trình nghiên cứu ứng dụng phương trình vi phân tuyến tính cấp 1 và cấp 2, biến đổi Laplace trong mô hình hóa dao động cơ học và dòng điện mạch RLC.', 'http://localhost:5000/uploads/materials/phuong-trinh-vi-phan-va-ung-dung-trong-mo-hinh-hoa-toan-hoc-1789397869451.pdf', 'PDF', 4681034, 220, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Đại số Tuyến tính Ứng dụng trong Khoa học Dữ liệu và Trí tuệ Nhân tạo', '[Tác giả: GS. Gilbert Strang (MIT OpenCourseWare & Department of Mathematics)] - Nền tảng toán học cho AI: phép phân rã ma trận giá trị suy biến SVD (Singular Value Decomposition), trực chuẩn hóa Gram-Schmidt và bài toán bình phương bé nhất.', 'http://localhost:5000/uploads/materials/dai-so-tuyen-tinh-ung-dung-trong-khoa-hoc-du-lieu-va-tri-tue-nhan-1789397873174.pdf', 'PDF', 24854165, 230, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giải tích Số và Phương pháp Tính trong Kỹ thuật', '[Tác giả: PGS.TS Trần Văn Hãn (Trường Đại học Bách Khoa Hà Nội - HUST)] - Cẩm nang phương pháp tính số: giải phương trình phi tuyến (phương pháp Newton-Raphson), đa thức nội suy Lagrange và tính xấp xỉ tích phân bằng công thức Simpson.', 'http://localhost:5000/uploads/materials/giai-tich-so-va-phuong-phap-tinh-trong-ky-thuat-1789397894265.pdf', 'PDF', 363274, 109, 28, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Lý thuyết Xác suất và Thống kê Toán học', '[Tác giả: PGS.TS Đào Hữu Hồ (NXB Đại học Quốc gia Hà Nội - VNU)] - Giáo trình kinh điển về lý thuyết xác suất: không gian biến cố sơ cấp, định lý cộng/nhân xác suất, công thức xác suất đầy đủ, công thức Bayes và biến ngẫu nhiên rời rạc.', 'http://localhost:5000/uploads/materials/giao-trinh-ly-thuyet-xac-suat-va-thong-ke-toan-hoc-1789397896153.pdf', 'PDF', 1104836, 162, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Xác suất và Thống kê Ứng dụng trong Kỹ thuật', '[Tác giả: PGS.TS Tống Đình Quỳ (NXB Bách Khoa Hà Nội)] - Giáo trình chuyên sâu về các phân phối xác suất quan trọng (Nhị thức, Poisson, Chuẩn Gaussian, Chi-bình phương, Student t) và phân tích các bài toán kỹ thuật thực nghiệm.', 'http://localhost:5000/uploads/materials/giao-trinh-xac-suat-va-thong-ke-ung-dung-trong-ky-thuat-1789397898638.pdf', 'PDF', 120645, 373, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Lý thuyết Xác suất và Thống kê Kinh tế', '[Tác giả: GS.TS Nguyễn Cao Văn, PGS.TS Trần Thái Ninh (Trường ĐH Kinh tế Quốc dân - NEU)] - Tài liệu đào tạo chuẩn mực về lý thuyết mẫu, phương pháp ước lượng tham số (khoảng tin cậy 95%, 99%), kiểm định giả thuyết thống kê và phân tích hồi quy tuyến tính.', 'http://localhost:5000/uploads/materials/giao-trinh-ly-thuyet-xac-suat-va-thong-ke-kinh-te-1789397899989.pdf', 'PDF', 1958911, 383, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Bài tập và Hướng dẫn Thực hành Xác suất Thống kê với Phần mềm R/SPSS', '[Tác giả: Khoa Toán - Thống kê (Trường Đại học Kinh tế TP.HCM - UEH)] - Hướng dẫn thực hành phân tích phương sai ANOVA một yếu tố và hai yếu tố, kiểm định tính độc lập Chi-Square và tính hệ số tương quan tuyến tính Pearson trên máy tính tính toán.', 'http://localhost:5000/uploads/materials/bai-tap-va-huong-dan-thuc-hanh-xac-suat-thong-ke-voi-phan-mem-r-s-1789397902396.pdf', 'PDF', 939692, 236, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('A First Course in Probability (Giáo trình Xác suất Toàn cầu)', '[Tác giả: GS. Sheldon Ross (University of Southern California)] - Bộ giáo trình xác suất mẫu mực toàn cầu: giải tích tổ hợp, kỳ vọng có điều kiện, hàm tạo mômen (Moment Generating Functions) và giới thiệu quá trình Poisson.', 'http://localhost:5000/uploads/materials/a-first-course-in-probability-giao-trinh-xac-suat-toan-cau-1789397904406.pdf', 'PDF', 558558, 112, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Thống kê Ứng dụng trong Phân tích Dữ liệu và Ra Quyết định', '[Tác giả: Viện Nghiên cứu Phát triển Quản lý (IVM)] - Cẩm nang phương pháp thống kê phi tham số: kiểm định dấu Wilcoxon, kiểm định Mann-Whitney, phân tích dữ liệu chuỗi thời gian (Time-series) và dự báo kinh tế định lượng.', 'http://localhost:5000/uploads/materials/thong-ke-ung-dung-trong-phan-tich-du-lieu-va-ra-quyet-dinh-1789397907744.pdf', 'PDF', 158891, 42, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Statistical Inference and Hypothesis Testing Manual (Stanford Methodology)', '[Tác giả: Department of Statistics (Stanford University)] - Cẩm nang phương pháp suy diễn thống kê hiện đại: ước lượng hợp lý cực đại MLE (Maximum Likelihood Estimation), kiểm soát sai lầm loại I (alpha) và loại II (beta), tính p-value.', 'http://localhost:5000/uploads/materials/statistical-inference-and-hypothesis-testing-manual-stanford-meth-1789397909633.pdf', 'PDF', 141971, 97, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Quy luật Số lớn và Định lý Giới hạn Trung tâm trong Khoa học Đương đại', '[Tác giả: Tạp chí Khoa học Toán học (Đại học Quốc gia TP.HCM)] - Công trình nghiên cứu ứng dụng định lý giới hạn trung tâm (Central Limit Theorem) trong phân tích dữ liệu lớn (Big Data), khử nhiễu tín hiệu và mô hình học máy xác suất.', 'http://localhost:5000/uploads/materials/quy-luat-so-lon-va-dinh-ly-gioi-han-trung-tam-trong-khoa-hoc-duon-1789397911062.pdf', 'PDF', 234449, 191, 29, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Triết học Mác - Lênin (Hệ Đại học Không chuyên Lý luận Chính trị)', '[Tác giả: Ban Tuyên giáo Trung ương & Bộ Giáo dục và Đào tạo (NXB Chính trị Quốc gia Sự thật)] - Giáo trình chuẩn quốc gia toàn diện: chủ nghĩa duy vật biện chứng, 3 quy luật cơ bản của phép biện chứng, 6 cặp phạm trù triết học và học thuyết hình thái kinh tế - xã hội.', 'http://localhost:5000/uploads/materials/giao-trinh-triet-hoc-mac-lenin-he-dai-hoc-khong-chuyen-ly-luan-ch-1789397912644.pdf', 'PDF', 1104836, 157, 30, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Pháp luật Đại cương: Lý luận Chung về Nhà nước và Pháp luật', '[Tác giả: Trường Đại học Luật Hà Nội & Trường ĐH Ngoại thương (FTU)] - Giáo trình cơ bản về nguồn gốc, bản chất và chức năng của Nhà nước và Pháp luật, hệ thống văn bản quy phạm pháp luật và bộ máy nhà nước Cộng hòa XHCN Việt Nam.', 'http://localhost:5000/uploads/materials/giao-trinh-phap-luat-dai-cuong-ly-luan-chung-ve-nha-nuoc-va-phap--1789397915334.pdf', 'PDF', 868492, 200, 30, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Hệ thống Pháp luật Việt Nam và Pháp luật Kinh tế Thực hành', '[Tác giả: Khoa Luật (Trường Đại học Kinh tế Quốc dân - NEU)] - Cẩm nang pháp lý về môi trường kinh doanh: quy chế thành lập doanh nghiệp theo Luật Doanh nghiệp, hợp đồng thương mại, quyền sở hữu trí tuệ và tranh chấp kinh tế.', 'http://localhost:5000/uploads/materials/giao-trinh-he-thong-phap-luat-viet-nam-va-phap-luat-kinh-te-thuc--1789397919018.pdf', 'PDF', 107346, 199, 30, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Lịch sử Triết học Phương Tây: Từ Cổ đại Hy Lạp đến Triết học Hiện đại', '[Tác giả: Khoa Triết học (Trường ĐH Khoa học Xã hội & Nhân văn - ĐHQG Hà Nội)] - Khảo cứu toàn diện tiến trình tư tưởng phương Tây: Socrates, Plato, Aristotle thời cổ đại, thuyết duy lý Descartes, triết học phê phán Kant và phép biện chứng Hegel.', 'http://localhost:5000/uploads/materials/lich-su-triet-hoc-phuong-tay-tu-co-dai-hy-lap-den-triet-hoc-hien--1789397920401.pdf', 'PDF', 317417, 206, 30, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Giáo trình Tư tưởng Hồ Chí Minh: Hệ thống Quan điểm Toàn diện và Sâu sắc', '[Tác giả: Bộ Giáo dục và Đào tạo (NXB Chính trị Quốc gia Sự thật)] - Giáo trình chính quy về hệ thống quan điểm của Chủ tịch Hồ Chí Minh: độc lập dân tộc gắn liền với CNXH, đại đoàn kết toàn dân, xây dựng nhà nước pháp quyền của dân, do dân, vì dân.', 'http://localhost:5000/uploads/materials/giao-trinh-tu-tuong-ho-chi-minh-he-thong-quan-diem-toan-dien-va-s-1789397922104.pdf', 'PDF', 120645, 499, 30, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Phương pháp Luận Biện chứng Duy vật trong Nghiên cứu Khoa học và Thực tiễn', '[Tác giả: Viện Triết học (Viện Hàn lâm Khoa học Xã hội Việt Nam - VASS)] - Phân tích mối quan hệ biện chứng giữa cái chung và cái riêng, nguyên nhân và kết quả, bản chất và hiện tượng; phương pháp luận phát hiện và giải quyết mâu thuẫn thực tiễn.', 'http://localhost:5000/uploads/materials/phuong-phap-luan-bien-chung-duy-vat-trong-nghien-cuu-khoa-hoc-va--1789397923458.pdf', 'PDF', 323091, 360, 30, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('Pháp luật Hợp đồng và Trách nhiệm Dân sự trong Hoạt động Thương mại', '[Tác giả: Trường Đại học Luật TP.HCM (ULAW)] - Chuyên khảo về điều kiện có hiệu lực của hợp đồng, chế tài bồi thường thiệt hại, phạt vi phạm và các trường hợp bất khả kháng theo quy định của Bộ luật Dân sự Việt Nam.', 'http://localhost:5000/uploads/materials/phap-luat-hop-dong-va-trach-nhiem-dan-su-trong-hoat-dong-thuong-m-1789397925110.pdf', 'PDF', 3433632, 500, 30, 2, 'active', NOW(), NOW());
INSERT INTO `materials` (`title`, `description`, `file_url`, `file_type`, `file_size`, `download_count`, `category_id`, `user_id`, `status`, `created_at`, `updated_at`) VALUES ('An Introduction to the Principles of Morals and Legislation (Triết học Pháp quyền)', '[Tác giả: Jeremy Bentham, John Stuart Mill (Oxford University Press Edition)] - Tác phẩm kinh điển về triết học pháp quyền phương Tây: nguyên lý vị lợi (Principle of Utility), cơ sở đạo đức học của luật pháp và lý thuyết về công lý xã hội.', 'http://localhost:5000/uploads/materials/an-introduction-to-the-principles-of-morals-and-legislation-triet-1789397928333.pdf', 'PDF', 1172762, 322, 30, 2, 'active', NOW(), NOW());
